// Template of oi-toolkit (skill oneidentity-imx-brand-theme): do not edit here, change the kit and reinstall.
import { DOCUMENT, Inject, Injectable, OnDestroy } from '@angular/core';
import { EuiTheme, EuiThemeService } from '@elemental-ui/core';
import { ClassloggerService } from 'qbm';
import { Subscription } from 'rxjs';
import { applyPatches, collectPatches, DeclarationPatch, revertPatches } from './brand-css-remap';
import { BrandColorMaps, BrandThemeConfig, readBrandColorMaps, readBrandThemeConfig } from './brand-theme-config';

/** Class of the ElementalUI dark theme: most dark-mode component rules are scoped to it. */
export const EUI_DARK_THEME = 'eui-dark-theme';

type ActiveTheme = 'none' | 'light' | 'dark';

// classList.add/remove rewrite the class attribute even when nothing changes (DOM "update steps"), and every
// rewrite is a new mutation for the body observer: change the classes only when needed, or the observer loops.
function addClass(classes: DOMTokenList, name: string): void {
  if (!classes.contains(name)) {
    classes.add(name);
  }
}

function removeClass(classes: DOMTokenList, name: string): void {
  if (classes.contains(name)) {
    classes.remove(name);
  }
}

/**
 * CCC: runtime support for the brand themes generated by the oi-toolkit kit (skill oneidentity-imx-brand-theme).
 * Identical for every customer: the theme classes and colors come from CSS variables of the theme files
 * (brand-theme-config.ts).
 *
 * 1. EuiThemeService puts exactly one class on <body>, so the brand dark class never gets the many component rules
 *    scoped to ".eui-dark-theme": this service adds that class too. ElementalUI removes it again on the next theme
 *    change (EuiThemeService.clearClasses).
 * 2. Upstream styles use the fixed One Identity palette: while a brand theme is active this service recolors those
 *    declarations in place (brand-css-remap), in every stylesheet including the component styles that Angular adds
 *    later (watched in <head>), and restores them afterwards.
 * 3. "Device theme" (EuiTheme.AUTO) follows the device with the brand themes instead of the standard ones, unless
 *    the brand declares --ccc-brand-device-theme: standard. EuiThemeService does not know the brand classes, so
 *    the service removes the class it added when the device changes mode or the user picks another theme.
 * 4. The theme CSS may load after the start: stylesheet loads trigger a new evaluation.
 *
 * Driven by the body class (MutationObserver), not by EuiThemeService events, because the service clears classes
 * in its own subscribers after emitting the new theme.
 */
@Injectable({
  providedIn: 'root',
})
export class BrandThemeService implements OnDestroy {
  private bodyObserver: MutationObserver | undefined;
  private headObserver: MutationObserver | undefined;
  private scanTimer: ReturnType<typeof setTimeout> | undefined;
  private activeTheme: ActiveTheme = 'none';
  /** Color maps of the active theme; undefined until its CSS is loaded. */
  private maps: BrandColorMaps | undefined;
  /** Applied patches per stylesheet; a sheet in this map has been recolored for the active theme. */
  private readonly patchesBySheet = new Map<CSSStyleSheet, readonly DeclarationPatch[]>();
  /** Theme chosen by the user (EuiThemeService switcher state), e.g. EuiTheme.AUTO. */
  private chosenTheme: string | undefined;
  private chosenThemeSubscription: Subscription | undefined;
  /** Brand class this service put on <body> for the device theme (Auto); EuiThemeService never removes it. */
  private deviceClass: string | undefined;

  constructor(
    @Inject(DOCUMENT) private readonly document: Document,
    private readonly logger: ClassloggerService,
    private readonly euiTheme: EuiThemeService,
  ) {}

  /** Starts watching the theme class, the chosen theme and the stylesheets; safe to call more than once. */
  public start(): void {
    if (this.bodyObserver) {
      return;
    }
    this.bodyObserver = new MutationObserver(() => this.safely(() => this.onBodyClassChanged()));
    this.bodyObserver.observe(this.document.body, { attributes: true, attributeFilter: ['class'] });
    this.headObserver = new MutationObserver((records) => this.safely(() => this.onHeadChanged(records)));
    this.headObserver.observe(this.document.head, { childList: true });
    this.watchLinkLoads(Array.from(this.document.querySelectorAll('link[rel="stylesheet"]')));
    this.chosenThemeSubscription = this.euiTheme.getThemeSwitcherState().subscribe((theme) => {
      this.chosenTheme = theme;
      this.safely(() => this.onBodyClassChanged());
    });
    this.safely(() => this.onBodyClassChanged());
  }

  /** Stops watching and restores the original colors. */
  public stop(): void {
    this.bodyObserver?.disconnect();
    this.bodyObserver = undefined;
    this.headObserver?.disconnect();
    this.headObserver = undefined;
    this.chosenThemeSubscription?.unsubscribe();
    this.chosenThemeSubscription = undefined;
    this.deactivate();
  }

  public ngOnDestroy(): void {
    this.stop();
  }

  /** Theme support is cosmetic: an error is logged and must never break the portal. */
  private safely(action: () => void): void {
    try {
      action();
    } catch (error) {
      this.logger.error(this, 'Brand theme: theme support failed', error);
    }
  }

  /** Auto: maps the class that EuiThemeService set for the device to the matching brand theme. */
  private syncDeviceTheme(classes: DOMTokenList, config: BrandThemeConfig | null): void {
    if (!config || config.deviceTheme !== 'brand' || this.chosenTheme !== EuiTheme.AUTO) {
      // Not (or no longer) mapped: drop the class added for the device, unless the user chose that very theme.
      if (this.deviceClass && this.deviceClass !== this.chosenTheme) {
        removeClass(classes, this.deviceClass);
      }
      this.deviceClass = undefined;
      return;
    }
    // EuiThemeService sets eui-light/eui-dark for the device; without them, our previous mapping is still valid.
    const target = classes.contains(EuiTheme.LIGHT)
      ? config.lightClass
      : classes.contains(EuiTheme.DARK)
        ? config.darkClass
        : this.deviceClass;
    if (!target) {
      return;
    }
    if (this.deviceClass && this.deviceClass !== target) {
      removeClass(classes, this.deviceClass);
    }
    addClass(classes, target);
    if (target === config.lightClass) {
      removeClass(classes, EuiTheme.LIGHT);
    }
    this.deviceClass = target;
  }

  private onBodyClassChanged(): void {
    const classes = this.document.body.classList;
    const config = readBrandThemeConfig(this.document);
    this.syncDeviceTheme(classes, config);
    const theme: ActiveTheme = !config
      ? 'none'
      : classes.contains(config.darkClass)
        ? 'dark'
        : classes.contains(config.lightClass)
          ? 'light'
          : 'none';

    if (theme === 'dark') {
      addClass(classes, EUI_DARK_THEME);
    }
    if (theme === this.activeTheme) {
      return;
    }
    if (theme === 'none') {
      this.deactivate();
      return;
    }
    // Light and dark use different maps: start again from the original colors.
    this.revertAll();
    this.activeTheme = theme;
    this.maps = undefined;
    this.scan();
  }

  private onHeadChanged(records: MutationRecord[]): void {
    const added = records
      .flatMap((record) => Array.from(record.addedNodes))
      .filter((node) => node instanceof HTMLStyleElement || node instanceof HTMLLinkElement);
    if (added.length === 0) {
      return;
    }
    this.watchLinkLoads(added.filter((node): node is HTMLLinkElement => node instanceof HTMLLinkElement));
    this.scheduleScan();
  }

  /** A <link> has no rules until it has loaded; the brand theme CSS itself may be one of them. */
  private watchLinkLoads(links: HTMLLinkElement[]): void {
    links
      .filter((link) => !link.sheet)
      .forEach((link) =>
        link.addEventListener('load', () => this.safely(() => this.scheduleScan()), { once: true }),
      );
  }

  /**
   * Coalesces the bursts of component styles that Angular adds while rendering a page. A new stylesheet may be the
   * brand theme CSS itself (already loaded or not): evaluate the theme again before scanning.
   */
  private scheduleScan(): void {
    if (this.scanTimer !== undefined) {
      return;
    }
    this.scanTimer = setTimeout(() => {
      this.scanTimer = undefined;
      this.safely(() => {
        this.onBodyClassChanged();
        if (this.activeTheme !== 'none') {
          this.scan();
        }
      });
    }, 0);
  }

  /** Recolors the stylesheets that have not been recolored yet. */
  private scan(): void {
    this.maps ??= readBrandColorMaps(this.document.body, this.activeTheme === 'dark') ?? undefined;
    if (!this.maps) {
      return; // CSS of the active theme not loaded yet: a stylesheet load triggers the next scan.
    }
    this.forgetDetachedSheets();
    const darkMode = this.activeTheme === 'dark';
    for (const sheet of Array.from(this.document.styleSheets)) {
      if (this.patchesBySheet.has(sheet)) {
        continue;
      }
      try {
        const patches = collectPatches(sheet.cssRules, darkMode, this.maps);
        applyPatches(patches);
        this.patchesBySheet.set(sheet, patches);
      } catch (error) {
        // Cross-origin stylesheets do not expose their rules: they keep their colors.
        this.logger.debug(this, `Brand theme: rules of ${sheet.href ?? 'inline style'} not readable`, error);
      }
    }
  }

  /** Angular removes the styles of destroyed components; a re-inserted <style> gets a new sheet. */
  private forgetDetachedSheets(): void {
    Array.from(this.patchesBySheet.keys())
      .filter((sheet) => !sheet.ownerNode || !(sheet.ownerNode as Node).isConnected)
      .forEach((sheet) => this.patchesBySheet.delete(sheet));
  }

  private revertAll(): void {
    this.patchesBySheet.forEach((patches) => revertPatches(patches));
    this.patchesBySheet.clear();
  }

  private deactivate(): void {
    this.activeTheme = 'none';
    this.maps = undefined;
    if (this.scanTimer !== undefined) {
      clearTimeout(this.scanTimer);
      this.scanTimer = undefined;
    }
    this.revertAll();
  }
}
